import { failure } from "./failures.js";
const MAX_FAILURE_MESSAGE_LENGTH = 512;
const POLICY_DENIAL = /Blocked by Playwright proxy: [A-Za-z]+\.[A-Za-z]+(?: \([^()\n]{1,300}\))?/u;
const CALL_LOG_MARKER = "\nCall log:\n";
const ANSI_ESCAPE = /\u001b\[[0-9;]*m/gu;
export const JOB_CODE_FILENAME = "<code>";
const JOB_CODE_FRAME = /^ +at .*<code>:\d+:\d+\)?$/u;
const MAX_JOB_CODE_FRAMES = 3;
export async function selectJobPage(contexts, pageGuid) {
    const open = contexts.flatMap((context) => context.pages()).filter((page) => !page.isClosed());
    const selected = open.find((page) => pageGuid !== undefined && Reflect.get(page, "_guid") === pageGuid) ??
        open[0];
    if (selected === undefined)
        return await contexts[0]?.newPage();
    if ((await selected.evaluate("document.visibilityState")) !== "visible") {
        await selected.bringToFront();
    }
    return selected;
}
export function browserSetupFailure(error) {
    return failure("worker_failed", boundedMessage(`Browser setup failed: ${describeError(error)}`));
}
export function jobCodeFailure(error) {
    const denied = POLICY_DENIAL.exec(errorMessage(error))?.[0];
    if (denied !== undefined)
        return failure("policy_denied", denied);
    return failure("job_failed", boundedMessage(describeError(error)));
}
function errorMessage(error) {
    if (typeof error === "string")
        return error;
    if (typeof error === "object" && error !== null && "message" in error) {
        return typeof error.message === "string" ? error.message : "";
    }
    return "";
}
function describeError(error) {
    const message = errorMessage(error);
    const firstLine = message.split("\n", 1)[0] ?? "";
    if (firstLine.length === 0)
        return "Unknown error";
    const name = typeof error === "object" && error !== null && "name" in error && typeof error.name === "string"
        ? error.name
        : "";
    const callLogStart = message.indexOf(CALL_LOG_MARKER);
    const callLog = callLogStart === -1 ? "" : message.slice(callLogStart).replaceAll(ANSI_ESCAPE, "").trimEnd();
    return `${name.length > 0 ? `${name}: ` : ""}${firstLine}${jobCodeFrames(error)}${callLog}`;
}
function jobCodeFrames(error) {
    const stack = typeof error === "object" && error !== null && "stack" in error ? error.stack : undefined;
    if (typeof stack !== "string")
        return "";
    const frames = stack
        .split("\n")
        .filter((line) => JOB_CODE_FRAME.test(line))
        .slice(0, MAX_JOB_CODE_FRAMES);
    return frames.map((frame) => `\n${frame}`).join("");
}
export function boundedMessage(message) {
    return message.length <= MAX_FAILURE_MESSAGE_LENGTH
        ? message
        : `${message.slice(0, MAX_FAILURE_MESSAGE_LENGTH - 1)}…`;
}
